    private ProfileAvatarView createAvatar(int sizeDp){ProfileAvatarView avatar=new ProfileAvatarView(this);avatar.setLayoutParams(new ViewGroup.LayoutParams(Ui.dp(this,sizeDp),Ui.dp(this,sizeDp)));avatar.showPlaceholder();loadAvatar(avatar,sizeDp);return avatar;}
    private void loadAvatar(ProfileAvatarView target,int sizeDp){String stored=getSharedPreferences("profile_avatar",0).getString(avatarPreferenceKey(),"");File file=stored.isEmpty()?avatarFile():new File(stored);if(!file.isFile()){target.showPlaceholder();return;}Object binding=new Object();target.setTag(binding);images.execute(()->{try{Bitmap bitmap=decodeAvatar(file,Ui.dp(this,sizeDp)*2);runOnUiThread(()->{if(!dead&&target.getTag()==binding&&bitmap!=null)target.showPhoto(bitmap);});}catch(Exception ignored){runOnUiThread(()->{if(!dead&&target.getTag()==binding)target.showPlaceholder();});}});}
    private Bitmap decodeAvatar(Uri uri,int targetSize)throws IOException{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("Imagem indisponível.");BitmapFactory.decodeStream(input,null,bounds);}int sample=1;while(bounds.outWidth/sample>targetSize*2||bounds.outHeight/sample>targetSize*2)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=Math.max(1,sample);try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("Imagem indisponível.");Bitmap bitmap=BitmapFactory.decodeStream(input,null,options);if(bitmap==null)throw new IOException("Não foi possível abrir a imagem.");return bitmap;}}
    private Bitmap decodeAvatar(File file,int targetSize)throws IOException{try(InputStream input=new FileInputStream(file)){Bitmap bitmap=BitmapFactory.decodeStream(input);if(bitmap==null)throw new IOException("Não foi possível abrir a imagem.");return bitmap;}}
    private File saveAvatar(Uri uri)throws IOException{Bitmap source=decodeAvatar(uri,1024);int side=Math.min(source.getWidth(),source.getHeight());int left=(source.getWidth()-side)/2,top=(source.getHeight()-side)/2;Bitmap square=Bitmap.createBitmap(source,left,top,side,side);Bitmap scaled=Bitmap.createScaledBitmap(square,512,512,true);File destination=avatarFile();try(OutputStream output=new FileOutputStream(destination)){if(!scaled.compress(Bitmap.CompressFormat.JPEG,90,output))throw new IOException("Não foi possível salvar a imagem.");}getSharedPreferences("profile_avatar",0).edit().putString(avatarPreferenceKey(),destination.getAbsolutePath()).apply();if(square!=source)square.recycle();if(scaled!=square)scaled.recycle();source.recycle();return destination;}
    private void chooseAvatar(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(intent,AVATAR);}
