    private void statistics(){long seconds=0;int pages=0,completed=0,started=0;for(LibraryStore.Book b:store.all()){seconds+=b.readingSeconds;pages+=b.readPages.length();if(b.completed)completed++;if(b.readPages.length()>0)started++;}LinearLayout p=page("Estatísticas pessoais");p.addView(Ui.text(this,"Os dados ficam somente neste dispositivo.",15,Ui.MUTED));p.addView(Ui.title(this,completed+" · "+I18n.t(this,"HQs concluídas"),22));p.addView(Ui.title(this,pages+" · "+I18n.t(this,"Páginas lidas"),22));p.addView(Ui.title(this,String.format(java.util.Locale.ROOT,"%dh %02dmin",seconds/3600,(seconds%3600)/60)+" · "+I18n.t(this,"Tempo de leitura"),22));p.addView(Ui.title(this,started+" · "+I18n.t(this,"HQs iniciadas"),22));}
