    private void setup2fa(){LinearLayout f=Ui.column(this);Ui.pad(f,18);EditText password=Ui.input(this,"Senha atual",true),current=Ui.input(this,"Código 2FA atual (se já estiver ativo)",false);f.addView(password);f.addView(current);new AlertDialog.Builder(this).setTitle("Configurar 2FA").setView(f).setPositiveButton("Continuar",(d,w)->{JSONObject[] setup={null};async("Preparando 2FA…",()->setup[0]=(JSONObject)api.json("POST","/account/2fa/setup",new JSONObject().put("current_password",password.getText().toString()).put("current_code",current.getText().length()==0?JSONObject.NULL:current.getText().toString())),()->confirm2fa(setup[0]));}).setNegativeButton("Cancelar",null).show();}
